B TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']\\n    \\n    def get_amount_from_line(line):\\n        # Look for something like 1,234.56 or 1234.56\\n        # Use a regex that finds numbers at the end of the line or after a keyword\\n        match = re.findall(r'\\\\d{1,3}(?:,\\\\d{3})*\\\\.\\\\d{2}', line)\\n        if match:\\n            return match[-1].replace(',', '')\\n        return None\\n\\n    found_amount = None\\n    for kw_pattern in keywords_priority:\\n        for i, line in enumerate(lines):\\n            if re.search(kw_pattern, line, re.IGNORECASE):\\n                # Check if this line contains an exclusion keyword\\n                if any(re.search(ex, line, re.IGNORECASE) for ex in exclusion_keywords):\\n                    # If it's just 'TOTAL' but also 'SUBTOTAL', we skip it if we are looking for 'TOTAL'\\n                    # However, if we are specifically looking for 'SUBTOTAL', it's different. \\n                    # But the requirement says skip lines with exclusion keywords.\\n                    # Let's be careful: if kw_pattern is 'TOTAL' and line is 'SUBTOTAL', skip.\\n                    # We should check if the keyword is actually present as a separate word or part of a larger word we want to avoid.\\n                    if kw_pattern.upper() == 'TOTAL' and 'SUBTOTAL' in line.upper().replace(' ', ''):\\n                        continue\\n                    if kw_pattern.upper() in ['TOTAL', 'AMOUNT']:\\n                         continue\\n\\n                amount = get_amount_from_line(line)\\n                if amount:\\n                    return amount\\n                # Fallback to next line\\n                if i + 1 \u003c len(lines):\\n                    amount = get_amount_from_line(lines[i+1])\\n                    if amount:\\n                        return amount\\n        if found_amount: break\\n\\n    return None\\n\\nimg_dir = '/app/workspace/dataset/img'\\nfiles = sorted([f for f in o